// Table measured on Java (JDK 21.0.2) by the probe `ProbeScore.java`
// (maintainer-only probe): `PointsCalculator.points`
// and `.value` over the probe contexts, `ScoreEngine.compute` over the probe inputs. The rows are
// not edited by hand — they are regenerated by the script `gen_swift.py`; the contexts and inputs with
// the same descriptions are in `PointsCalculatorTests` and `ScoreEngineTests`.

@testable import MCLCore

enum ScoreMeasured {
    enum Outcome: Sendable, Equatable {
        case value(Int32)
        /// qsoCount, qsoPoints, multTotal, multByGroup in order, bonusPoints, qtcPoints, total.
        case state(Int32, Int64, Int32, [Group], Int64, Int64, Int64)
        case error(ExpressionError.Kind, String)
        /// Java fails with a NullPointerException; Swift is lenient (a deliberate divergence from Java v1.1.1).
        case npe
    }

    struct Group: Sendable, Equatable {
        let key: String?
        let value: Int32

        init(_ key: String?, _ value: Int32) {
            self.key = key
            self.value = value
        }
    }

    struct Row: Sendable, CustomStringConvertible {
        let name: String
        let context: String
        let java: Outcome

        init(_ name: String, _ context: String, _ java: Outcome) {
            self.name = name
            self.context = context
            self.java = java
        }

        var description: String { name + " @" + context }
    }

    struct StateRow: Sendable, CustomStringConvertible {
        let name: String
        let input: Int
        let java: Outcome

        init(_ name: String, _ input: Int, _ java: Outcome) {
            self.name = name
            self.input = input
            self.java = java
        }

        var description: String { name + " #" + String(input) }
    }

